package com.cob.emr.ddd.domain.medicalnote.model.objective;import lombok.Builder;import lombok.Getter;import java.util.List;import java.util.stream.Collectors;@Getter@Builder(toBuilder = true)public class ObjectiveFindings {    private final List<String> precautions;    private final String preTreatmentFindings;    private final String postTreatmentFindings;    private final String clinicalObservations;    private final List<PerformedIntervention> performedInterventions;    private final String instructions;        public ObjectiveFindings excludeEvaluationCodes() {        if (performedInterventions == null) return this;                List<PerformedIntervention> filtered = performedInterventions.stream()            .filter(intervention -> !intervention.isEvaluationCode())            .collect(Collectors.toList());                    return this.toBuilder()            .performedInterventions(filtered)            .build();    }}
